import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Single fused elementwise Tanh kernel (fast-math optimized).
// tanh(x) = sign(x) * (1 - e) / (1 + e), e = __expf(-2*|x|) in (0, 1]:
// numerically stable, branch-free, low instruction count. float4
// vectorized loads/stores with evict-first streaming hints (__ldcs/
// __stcs) keep L2 clean for this purely streaming, zero-reuse kernel.
// Optimization (new): increase memory-level parallelism per warp.
// Profiler shows 90.3% DRAM throughput with 100% theoretical /
// 90.5% achieved occupancy, i.e. the kernel is limited by loads in
// flight, not by warp count: with a single float4 payload each warp
// stalls on its one outstanding load every iteration, so 64 warps/SM
// sustain only ~1KB of outstanding reads per SM -- short of the
// bandwidth-delay product of the DRAM pipeline. Unrolling the
// grid-stride loop x4 issues four independent 16B streaming loads
// back-to-back before the first result is consumed (4x MLP per
// warp). __launch_bounds__(256, 6) trades 25% occupancy for a
// 42-register budget so the 16 data registers never spill.
// The last (up to 3) tail elements are handled by the first
// threads, so exactly one kernel launch is needed.
__device__ __forceinline__ float fast_tanhf(float x) {
    const float e = __expf(-2.0f * fabsf(x));  // in (0, 1], never overflows
    const float t = __fdividef(1.0f - e, 1.0f + e);
    return copysignf(t, x);
}
__global__ void __launch_bounds__(256, 6) tanh_kernel(
                            const float* __restrict__ in,
                            float* __restrict__ out,
                            const long n) {
    const long n4 = n >> 2;  // number of full float4 groups
    const long tid = (long)blockIdx.x * blockDim.x + threadIdx.x;
    const long stride = (long)gridDim.x * blockDim.x;
    const float4* in4  = reinterpret_cast<const float4*>(in);
    float4*       out4 = reinterpret_cast<float4*>(out);
    long idx = tid;
    const long s2 = stride << 1;
    const long s3 = s2 + stride;
    // Unrolled main loop: four independent float4 streaming loads are
    // issued back-to-back before any result is consumed, keeping 4x
    // more bytes in flight per warp to saturate the DRAM pipeline.
    for (; idx + s3 < n4; idx += (stride << 2)) {
        float4 a = __ldcs(&in4[idx]);
        float4 b = __ldcs(&in4[idx + stride]);
        float4 c = __ldcs(&in4[idx + s2]);
        float4 d = __ldcs(&in4[idx + s3]);
        a.x = fast_tanhf(a.x);
        a.y = fast_tanhf(a.y);
        a.z = fast_tanhf(a.z);
        a.w = fast_tanhf(a.w);
        b.x = fast_tanhf(b.x);
        b.y = fast_tanhf(b.y);
        b.z = fast_tanhf(b.z);
        b.w = fast_tanhf(b.w);
        c.x = fast_tanhf(c.x);
        c.y = fast_tanhf(c.y);
        c.z = fast_tanhf(c.z);
        c.w = fast_tanhf(c.w);
        d.x = fast_tanhf(d.x);
        d.y = fast_tanhf(d.y);
        d.z = fast_tanhf(d.z);
        d.w = fast_tanhf(d.w);
        __stcs(&out4[idx], a);
        __stcs(&out4[idx + stride], b);
        __stcs(&out4[idx + s2], c);
        __stcs(&out4[idx + s3], d);
    }
    // Cleanup loop for the remaining float4 groups.
    for (; idx < n4; idx += stride) {
        float4 a = __ldcs(&in4[idx]);
        a.x = fast_tanhf(a.x);
        a.y = fast_tanhf(a.y);
        a.z = fast_tanhf(a.z);
        a.w = fast_tanhf(a.w);
        __stcs(&out4[idx], a);
    }
    const long tail_start = n4 << 2;
    if (tid < n - tail_start) {
        const long i = tail_start + tid;
        __stcs(&out[i], fast_tanhf(__ldcs(&in[i])));
    }
}

torch::Tensor tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    auto out = torch::empty_like(x);
    const long n = x.numel();
    if (n == 0) return out;

    // Launch config: persistent grid sized to exactly fill the device
    // under __launch_bounds__(256, 6) (SMs * 6 blocks of 256 threads =
    // 1536 resident threads per SM). The x4-unrolled grid-stride loop
    // covers all float4 groups; fewer resident warps are compensated
    // by 4 outstanding streaming loads per warp. Memory access
    // pattern, vectorization, and semantics are unchanged.
    const int threads = 256;
    const long n4 = (n + 3) >> 2;
    long blocks = (n4 + threads - 1) / threads;
    int num_sms = 0;
    cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount,
                           x.get_device());
    const long max_blocks = (long)num_sms * 6L;
    if (blocks > max_blocks) blocks = max_blocks;

    tanh_kernel<<<(int)blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        n);

    return out;
}
"""

cpp_src = "torch::Tensor tanh_forward(torch::Tensor x);"

_tanh_mod = load_inline(
    name="tanh_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["tanh_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _tanh_mod.tanh_forward(x)

